@using sv_8b59cee9507e49a08b74ee2b3e1e0065.Services

<section class="profile-section" aria-label="Profile settings">
    <h2>Profile</h2>

    @if (successMessage is not null)
    {
        <div class="toast success" role="status">✓ @successMessage</div>
    }

    <div class="avatar-area">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(editAvatarUrl))
            {
                <img src="@editAvatarUrl" alt="Avatar for @editDisplayName" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
        </div>
        <span class="avatar-url" title="@editAvatarUrl">@TruncateUrl(editAvatarUrl)</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="editDisplayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="editEmail" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="editBio" @bind:event="oninput"></textarea>
    </div>

    <div class="button-row">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@(!HasChanges || saving)">
            @(saving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn-secondary" @onclick="Discard" disabled="@(!HasChanges)">
            Discard Changes
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired]
    public UserProfile Profile { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSaved { get; set; }

    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";
    private bool saving;
    private string? successMessage;

    private bool HasChanges =>
        editDisplayName != Profile.DisplayName ||
        editEmail != Profile.Email ||
        editBio != Profile.Bio;

    protected override void OnParametersSet()
    {
        ResetToProfile();
    }

    private void ResetToProfile()
    {
        editDisplayName = Profile.DisplayName;
        editEmail = Profile.Email;
        editAvatarUrl = Profile.AvatarUrl;
        editBio = Profile.Bio;
        successMessage = null;
    }

    private async Task SaveAsync()
    {
        saving = true;
        successMessage = null;
        try
        {
            var updated = Profile with
            {
                DisplayName = editDisplayName,
                Email = editEmail,
                Bio = editBio
            };
            await OnSaved.InvokeAsync(updated);
            successMessage = "Profile saved successfully!";
        }
        finally
        {
            saving = false;
        }
    }

    private void Discard()
    {
        ResetToProfile();
    }

    private static string TruncateUrl(string? url) =>
        string.IsNullOrWhiteSpace(url) ? "(no avatar)" :
        url.Length > 40 ? url[..37] + "…" : url;
}

.profile-section {
    max-width: 600px;
}

h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

.toast.success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid var(--border-color, #ddd);
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f0f0f0;
    flex-shrink: 0;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.avatar-url {
    font-size: 0.8rem;
    color: #666;
    word-break: break-all;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 600;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.button-row {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary,
.btn-secondary {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    border: 1px solid transparent;
}

.btn-primary {
    background-color: #1a73e8;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1557b0;
}

.btn-secondary {
    background-color: #fff;
    color: #333;
    border-color: #ccc;
}

.btn-secondary:hover:not(:disabled) {
    background-color: #f5f5f5;
}

.btn-primary:disabled,
.btn-secondary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

