{"file_text": "@using sv_8b59cee9507e49a08b74ee2b3e1e0065.Services

<section class="notifications-section" aria-label="Notification preferences">
    <h2>Notifications</h2>

    @if (successMessage is not null)
    {
        <div class="toast success" role="status">✓ @successMessage</div>
    }

    <div class="toggle-group">
        <label class="toggle-row">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
        </label>
        <label class="toggle-row">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
        </label>
        <label class="toggle-row">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
        </label>
    </div>

    @if (mutedChannels.Count > 0)
    {
        <div class="muted-channels">
            <h3>Muted Channels</h3>
            <ul>
                @foreach (var channel in allChannels)
                {
                    <li>
                        <label class="channel-row">
                            <input type="checkbox"
                                   checked="@mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                        </label>
                    </li>
                }
            </ul>
        </div>
    }

    <div class="button-row">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@saving">
            @(saving ? "Saving…" : "Save Preferences")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSaved { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = [];
    private List<string> allChannels = [];
    private bool saving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        emailNotifications = Prefs.EmailNotifications;
        pushNotifications = Prefs.PushNotifications;
        weeklyDigest = Prefs.WeeklyDigest;
        allChannels = [.. Prefs.MutedChannels];
        mutedChannels = [.. Prefs.MutedChannels];
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        successMessage = null;
        try
        {
            var updated = new NotificationPrefs(
                emailNotifications,
                pushNotifications,
                weeklyDigest,
                [.. mutedChannels]
            );
            await OnSaved.InvokeAsync(updated);
            successMessage = "Notification preferences saved!";
        }
        finally
        {
            saving = false;
        }
    }
}
