.notifications-section {
    max-width: 600px;
}

h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.toast.success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid var(--border-color, #eee);
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-switch {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

.muted-channels {
    margin-bottom: 1.5rem;
}

.muted-channels ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.channel-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.button-row {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    border: 1px solid transparent;
    background-color: #1a73e8;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

