{"file_text": "<div class="password-panel">
    <button class="panel-header" @onclick="ToggleExpanded"
            aria-expanded="@expanded" aria-controls="password-form">
        <span>🔑 Change Password</span>
        <span class="chevron @(expanded ? "open" : "")">▸</span>
    </button>

    @if (expanded)
    {
        <div id="password-form" class="panel-body">
            @if (message is not null)
            {
                <div class="toast @(isError ? "error" : "success")" role="status">@message</div>
            }

            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm New Password</label>
                <input id="confirmPassword" type="password" @bind="confirmPassword" />
            </div>

            <button class="btn-primary" @onclick="UpdatePasswordAsync"
                    disabled="@(!CanSubmit || submitting)">
                @(submitting ? "Updating…" : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool expanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool submitting;
    private string? message;
    private bool isError;

    private bool CanSubmit =>
        !string.IsNullOrWhiteSpace(currentPassword) &&
        !string.IsNullOrWhiteSpace(newPassword) &&
        newPassword == confirmPassword;

    private void ToggleExpanded() => expanded = !expanded;

    private async Task UpdatePasswordAsync()
    {
        if (newPassword != confirmPassword)
        {
            message = "Passwords do not match.";
            isError = true;
            return;
        }

        submitting = true;
        message = null;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            message = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            message = $"Failed to update password: {ex.Message}";
            isError = true;
        }
        finally
        {
            submitting = false;
        }
    }
}
