toolArgs.file_text:
.password-panel {
    border: 1px solid var(--border-color, #ddd);
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    border: none;
    background: var(--panel-bg, #f9f9f9);
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
}

.panel-header:hover {
    background: var(--panel-hover, #f0f0f0);
}

.chevron {
    transition: transform 0.2s;
}

.chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid var(--border-color, #ddd);
}

.toast {
    border-radius: 6px;
    padding: 0.6rem 0.85rem;
    margin-bottom: 1rem;
    font-size: 0.85rem;
}

.toast.success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.toast.error {
    background-color: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 600;
    font-size: 0.85rem;
}

.form-group input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 6px;
    font-size: 0.9rem;
    box-sizing: border-box;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    border: 1px solid transparent;
    background-color: #1a73e8;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

