@if (Visible)
{
    <div class="dialog-overlay" @onclick="OnCancel.InvokeAsync">
        <div class="dialog" role="alertdialog" aria-labelledby="dialog-title"
             @onclick:stopPropagation="true">
            <h3 id="dialog-title">Revoke Session</h3>
            <p>
                Are you sure you want to revoke the session on
                <strong>@Device</strong> in <strong>@Location</strong>?
            </p>
            <p class="hint">This will sign out that device immediately.</p>
            <div class="dialog-actions">
                <button class="btn-danger" @onclick="OnConfirm.InvokeAsync">Revoke</button>
                <button class="btn-secondary" @onclick="OnCancel.InvokeAsync">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public string Device { get; set; } = "";
    [Parameter] public string Location { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }
}

.dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
