@using sv_8b59cee9507e49a08b74ee2b3e1e0065.Services

<div class="sessions-area">
    <h3>Active Sessions</h3>

    @if (Sessions.Count == 0)
    {
        <p class="empty">No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn-revoke" @onclick="() => RequestRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
</div>

<RevokeSessionDialog
    Visible="@(sessionToRevoke is not null)"
    Device="@(sessionToRevoke?.Device ?? "")"
    Location="@(sessionToRevoke?.Location ?? "")"
    OnConfirm="ConfirmRevoke"
    OnCancel="CancelRevoke" />

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? sessionToRevoke;

    private void RequestRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }
}

