arguments.file_text:
@using sv_8b59cee9507e49a08b74ee2b3e1e0065.Services

<section class="security-section" aria-label="Security settings">
    <h2>Security</h2>

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="twofa-area">
        <h3>Two-Factor Authentication</h3>
        <label class="twofa-row">
            <span class="twofa-status">
                <span class="status-dot @(TwoFactorEnabled ? "enabled" : "disabled")"></span>
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
            <input type="checkbox" checked="@TwoFactorEnabled"
                   @onchange="e => OnTwoFactorToggled.InvokeAsync((bool)e.Value!)" />
        </label>
        @if (LastPasswordChange.HasValue)
        {
            <p class="last-changed">
                Last password change: @LastPasswordChange.Value.ToString("MMM d, yyyy")
            </p>
        }
    </div>

    <ActiveSessionsTable Sessions="Sessions"
                         CurrentSessionId="@Sessions.FirstOrDefault()?.Id"
                         OnRevoke="OnRevokeSession" />
</section>

@code {
    [Parameter] public bool TwoFactorEnabled { get; set; }
    [Parameter] public DateTime? LastPasswordChange { get; set; }
    [Parameter] public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<bool> OnTwoFactorToggled { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }
}

.security-section {
    max-width: 700px;
}

h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.twofa-area {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid var(--border-color, #ddd);
    border-radius: 8px;
}

.twofa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    padding: 0.5rem 0;
}

.twofa-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 600;
}

.status-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    display: inline-block;
}

.status-dot.enabled {
    background-color: #28a745;
}

.status-dot.disabled {
    background-color: #dc3545;
}

.last-changed {
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.5rem;
    margin-bottom: 0;
}

.appearance-preview {
    border: 1px solid var(--border-color, #ddd);
    border-radius: 8px;
    overflow: hidden;
    margin-top: 1.5rem;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
    font-size: 0.8rem;
    opacity: 0.7;
}

.preview-body {
    display: flex;
    flex-direction: column;
    gap: var(--preview-gap, 0.75rem);
}

.preview-body p {
    margin: 0;
}

.preview-card {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    border: 1px solid rgba(128, 128, 128, 0.25);
    border-radius: 6px;
    font-size: 0.9em;
}

@using sv_8b59cee9507e49a08b74ee2b3e1e0065.Services

<section class="appearance-section" aria-label="Appearance settings">
    <h2>Appearance</h2>

    @if (successMessage is not null)
    {
        <div class="toast success" role="status">✓ @successMessage</div>
    }

    <div class="setting-group">
        <h3>Theme</h3>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-option">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="setting-group">
        <h3>Font Size</h3>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-option">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="setting-group">
        <h3>Language</h3>
        <select @bind="selectedLanguage" class="language-select">
            @foreach (var lang in Languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="setting-group">
        <label class="toggle-row">
            <span>Compact Mode</span>
            <input type="checkbox" @bind="compactMode" />
        </label>
    </div>

    <AppearancePreview Theme="@selectedTheme"
                       FontSize="@selectedFontSize"
                       CompactMode="@compactMode" />

    <div class="button-row">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@saving">
            @(saving ? "Saving…" : "Save")
        </button>
    </div>
</section>

@code {
    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    [Parameter, EditorRequired]
    public AppearanceSettings Settings { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSaved { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private bool saving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        selectedTheme = Settings.Theme;
        selectedFontSize = Settings.FontSize;
        selectedLanguage = Settings.Language;
        compactMode = Settings.CompactMode;
    }

    private async Task SaveAsync()
    {
        saving = true;
        successMessage = null;
        try
        {
            var updated = new AppearanceSettings(
                selectedTheme, selectedFontSize, selectedLanguage, compactMode);
            await OnSaved.InvokeAsync(updated);
            successMessage = "Appearance settings saved!";
        }
        finally
        {
            saving = false;
        }
    }
}

.appearance-section {
    max-width: 600px;
}

h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.toast.success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.setting-group {
    margin-bottom: 1.25rem;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.language-select {
    padding: 0.45rem 0.75rem;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 6px;
    font-size: 0.9rem;
    min-width: 200px;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    cursor: pointer;
}

.button-row {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    border: 1px solid transparent;
    background-color: #1a73e8;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

