toolArgs.file_text:
.appearance-section {
    max-width: 600px;
}

h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.toast.success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.setting-group {
    margin-bottom: 1.25rem;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.language-select {
    padding: 0.45rem 0.75rem;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 6px;
    font-size: 0.9rem;
    min-width: 200px;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    cursor: pointer;
}

.button-row {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    border: 1px solid transparent;
    background-color: #1a73e8;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

