@using sv_8b59cee9507e49a08b74ee2b3e1e0065.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="section => activeSection = section" />

    <main class="settings-content">
        @if (loading)
        {
            <p class="loading">Loading settings…</p>
        }
        else if (error is not null)
        {
            <div class="toast error" role="alert">@error</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile!" OnSaved="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@notificationPrefs!" OnSaved="SaveNotificationsAsync" />
                    break;
                case "Security":
                    <SecuritySection TwoFactorEnabled="@securitySettings!.TwoFactorEnabled"
                                     LastPasswordChange="@securitySettings.LastPasswordChange"
                                     Sessions="@securitySettings.Sessions"
                                     OnChangePassword="HandleChangePasswordAsync"
                                     OnTwoFactorToggled="HandleTwoFactorToggled"
                                     OnRevokeSession="HandleRevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@appearanceSettings!" OnSaved="SaveAppearanceAsync" />
                    break;
            }
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool loading = true;
    private string? error;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifsTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

            profile = profileTask.Result;
            notificationPrefs = notifsTask.Result;
            securitySettings = securityTask.Result;
            appearanceSettings = appearanceTask.Result;
        }
        catch (Exception ex)
        {
            error = $"Failed to load settings: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private void HandleTwoFactorToggled(bool enabled)
    {
        // Reflects the toggle; a real app would call the service here
        securitySettings = securitySettings! with { TwoFactorEnabled = enabled };
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 10px;
    overflow: hidden;
    background: #fff;
    margin: 1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.loading {
    color: #888;
    font-size: 0.95rem;
}

.toast.error {
    background-color: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    font-size: 0.9rem;
}

